# own check: Bellman-Ford style relaxation on the DAG + Dijkstra trace + exhaustive path enumeration
import heapq, itertools
W = {('S','A'):3,('S','B'):2,('A','B'):2,('A','C'):6,('B','C'):3,('B','D'):6,
     ('C','E'):2,('C','T'):6,('D','E'):8,('D','T'):2,('E','T'):3}
def dijkstra(W):
    adj = {}
    for (u, v), w in W.items(): adj.setdefault(u, []).append((v, w))
    dist = {'S': 0}; fin = []; pq = [(0, 'S')]
    while pq:
        d, u = heapq.heappop(pq)
        if u in fin: continue
        fin.append(u)
        for v, w in adj.get(u, []):
            if d + w < dist.get(v, float('inf')):
                dist[v] = d + w; heapq.heappush(pq, (d + w, v))
    return dist, fin
def bellman(W):
    dist = {v: float('inf') for e in W for v in e}; dist['S'] = 0
    for _ in range(len(dist)):
        for (u, v), w in W.items(): dist[v] = min(dist[v], dist[u] + w)
    return dist
def all_paths(W, s, t):
    out = []
    def go(u, path, c):
        if u == t: out.append((c, tuple(path))); return
        for (a, b), w in W.items():
            if a == u: go(b, path + [b], c + w)
    go(s, [s], 0); return sorted(out)
dist, order = dijkstra(W)
assert dist == {k: v for k, v in bellman(W).items() if k in dist}
best = all_paths(W, 'S', 'T')
ties = [p for c, p in best if c == best[0][0]]
W2 = dict(W); W2[('B', 'D')] = 8
print(order, dist, ties)
